('hab_nota_dissonante', 'nota_dissonante', 'Nota Dissonante', 'Uma nota aguda em linha reta que fere o primeiro inimigo no caminho.', 'BARDO', 'SKILLSHOT', 'ARCANO', 'minecraft:note_block', 10, 2, 6, 20, 0, 0, '', 0, 1, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_cancao_da_marcha', 'cancao_da_marcha', 'Canção da Marcha', 'Canção por 15 s: você e os aliados a até 10 blocos correm mais (Velocidade II) e saltam mais alto. Só uma canção toca por vez.', 'BARDO', 'BUFF', 'ARCANO', 'minecraft:rabbit_foot', 25, 22, 0, 0, 10, 15, 'frx:cancao_marcha', 2, 2, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_acorde_cortante', 'acorde_cortante', 'Acorde Cortante', 'Um acorde em leque à sua frente que fere e empurra todos.', 'BARDO', 'AREA', 'ARCANO', 'minecraft:amethyst_shard', 22, 7, 6, 7, 0, 0, 'frx:leque', 0, 4, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_balada_restauradora', 'balada_restauradora', 'Balada Restauradora', 'Canção por 10 s: a cada segundo cura você e os aliados a até 10 blocos. Só uma canção toca por vez.', 'BARDO', 'BUFF', 'NATUREZA', 'minecraft:golden_apple', 35, 24, -2, 0, 10, 10, 'frx:cancao_cura', 0, 5, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_cancao_de_ninar', 'cancao_de_ninar', 'Canção de Ninar', 'Os inimigos a até 6 blocos adormecem por 4 s: param, esquecem o alvo e batem fraco. Em chefes dura um terço.', 'BARDO', 'AREA', 'ARCANO', 'minecraft:white_bed', 30, 26, 0, 0, 6, 4, 'frx:ninar', 0, 7, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_hino_de_guerra', 'hino_de_guerra', 'Hino de Guerra', 'Canção por 12 s: você e os aliados a até 10 blocos causam 15% a mais de dano. Só uma canção toca por vez.', 'BARDO', 'BUFF', 'FOGO', 'minecraft:goat_horn', 40, 30, 0, 0, 10, 12, 'frx:cancao_guerra', 3, 8, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_zombaria', 'zombaria', 'Zombaria', 'Humilha o alvo: por 8 s ele brilha, bate mais fraco e leva 20% a mais de dano de todo mundo.', 'BARDO', 'ALVO', 'ARCANO', 'minecraft:carved_pumpkin', 25, 16, 4, 18, 0, 8, 'frx:zombaria', 2, 10, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_passo_de_danca', 'passo_de_danca', 'Passo de Dança', 'Um giro rápido para trás, para sair do alcance dos inimigos.', 'BARDO', 'MOBILIDADE', 'FISICO', 'minecraft:leather_boots', 15, 8, 0, -7, 0, 0, '', 0, 12, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_refrao_ecoante', 'refrao_ecoante', 'Refrão Ecoante', 'Encurta em 30% as recargas em andamento dos aliados a até 10 blocos e devolve 15 de recurso a cada um. Sozinho, encurta as suas em 15%.', 'BARDO', 'BUFF', 'ARCANO', 'minecraft:echo_shard', 45, 40, 0, 0, 10, 0, 'frx:eco', 3, 14, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_crescendo', 'crescendo', 'Crescendo', 'A música explode numa onda sonora que fere todos os inimigos em volta de você.', 'BARDO', 'AREA', 'ARCANO', 'minecraft:bell', 40, 14, 10, 0, 6, 0, '', 0, 16, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_cancao_do_heroi', 'cancao_do_heroi', 'Canção do Herói', 'Canta os feitos do aliado na mira (sem mira, os seus): por 10 s ele causa 30% a mais de dano, corre, regenera e ganha corações extras.', 'BARDO', 'BUFF', 'SAGRADO', 'minecraft:golden_helmet', 50, 50, 0, 16, 0, 10, 'frx:heroi', 3, 18, false, 'ITEM', CURRENT_TIMESTAMP),
('hab_sinfonia_final', 'sinfonia_final', 'Sinfonia Final', 'Por 10 s, todas as canções de uma vez: a cada segundo você e os aliados a até 12 blocos curam, correm e causam 20% a mais de dano; os inimigos levam dano e ficam lentos e fracos.', 'BARDO', 'AREA', 'ARCANO', 'minecraft:music_disc_pigstep', 100, 120, 6, 0, 12, 10, 'frx:sinfonia', 2, 25, true, 'NIVEL', CURRENT_TIMESTAMP),
('hab_palma_de_ferro', 'palma_de_ferro', 'Palma de Ferro', 'Uma palma no peito que arremessa o alvo para longe e o deixa lento por 2 s.', 'MONGE', 'ALVO', 'FISICO', 'minecraft:rabbit_hide', 20, 5, 6, 4.5, 0, 2, 'frx:palma', 0, 1, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_passo_do_vento', 'passo_do_vento', 'Passo do Vento', 'Avança 8 blocos num piscar, ferindo quem estiver no caminho.', 'MONGE', 'MOBILIDADE', 'FISICO', 'minecraft:feather', 15, 6, 3, 8, 0, 0, '', 0, 2, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_rajada_de_socos', 'rajada_de_socos', 'Rajada de Socos', 'Seis socos em um segundo no alvo da mira. O último vale o dobro e o empurra.', 'MONGE', 'ALVO', 'FISICO', 'minecraft:blaze_powder', 30, 10, 2.5, 4.5, 0, 0, 'frx:rajada', 6, 4, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_chute_giratorio', 'chute_giratorio', 'Chute Giratório', 'Um giro que acerta todos os inimigos em volta de você.', 'MONGE', 'AREA', 'FISICO', 'minecraft:leather_boots', 25, 8, 6, 0, 3.5, 0, '', 0, 5, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_meditacao', 'meditacao', 'Meditação', 'Respira fundo por 4 s (você anda mais devagar): recupera vida e 40 de chi, e limpa veneno, definhamento, fraqueza, cegueira e fogo. Não gasta chi.', 'MONGE', 'BUFF', 'ARCANO', 'minecraft:lily_pad', 0, 28, -2, 0, 0, 4, 'frx:meditar', 5, 7, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_chute_ascendente', 'chute_ascendente', 'Chute Ascendente', 'Um chute de baixo para cima que arremessa para o alto os inimigos em volta e dá corações extras a você.', 'MONGE', 'AREA', 'FISICO', 'minecraft:slime_ball', 30, 12, 6, 0, 3, 0, 'frx:lancar', 1, 8, false, 'NIVEL', CURRENT_TIMESTAMP),
